@Composable fun ContentBox( modifier: Modifier = Modifier, color: Color = JewelTheme.globalColors.borders.disabled, shape: Shape = RoundedCornerShape(JewelTheme.tooltipStyle.metrics.cornerSize), content: @Composable BoxScope.() -> Unit, ) { val panelBackground = JewelTheme.globalColors.panelBackground
